// Normalise la reponse d'Ollama en champs stables.
// Supporte : structured outputs (format=schema), JSON brut, ou texte avec objet imbrique.
const data = $input.first().json;
const theme = $('Theme Picker').first().json.theme;

const raw = data.response ?? data.message?.content ?? '';
let parsed = null;

const tryParse = (s) => { try { return JSON.parse(s); } catch (_) { return null; } };

if (typeof raw === 'object' && raw !== null) parsed = raw;
else {
  parsed = tryParse(String(raw));
  if (!parsed) {
    const m = String(raw).match(/\{[\s\S]*\}/);
    if (m) parsed = tryParse(m[0]);
  }
}

const repair = (s) => {
  let t = String(s).trim();
  const lastKey = Math.max(t.lastIndexOf(':"'), t.lastIndexOf('",'), t.lastIndexOf(',"'));
  if (lastKey > 0) t = t.slice(0, lastKey + 1);
  t = t.replace(/"[^"]*$/s, '');
  let depth = 0;
  for (const ch of t) { if (ch === '{') depth++; else if (ch === '}') depth--; }
  return tryParse(t + '"' + '}'.repeat(Math.max(0, depth)));
};

// Si la generation a ete tronquee (done_reason=length), le JSON est
// invalide : on le repare plutot que de perdre la generation.
if (!parsed) parsed = repair(raw);

const field = (k) => {
  const v = parsed?.[k];
  return typeof v === 'string' ? v.trim() : '';
};

const hook = field('hook');
const body = field('body');
const call_to_action = field('call_to_action');

if (!hook && !body && !call_to_action) {
  throw new Error(
    'Reponse LLM inexploitable (modele=' + (data.model || 'n/a') +
    ', done_reason=' + (data.done_reason || 'n/a') +
    ', eval_count=' + (data.eval_count != null ? data.eval_count : 'n/a') +
    '). Brut: ' + String(raw).slice(0, 300)
  );
}

// Le message Telegram est envoye en parse_mode Markdown (legacy).
// Sans echappement, un simple "_" ou "*" produit par le modele fait
// echouer l'API Telegram en 400 "can't parse entities".
const md = (s) => String(s).replace(/([_*`[\]])/g, '\\$1');

return [{
  json: {
    theme,
    hook,
    body,
    call_to_action,
    // versions echappees, pretes pour Telegram
    hook_md: md(hook),
    body_md: md(body),
    cta_md: md(call_to_action),
    complete: !!(hook && body && call_to_action),
    model: data.model ?? 'llama3.2:3b',
    total_duration_ms: typeof data.total_duration === 'number' ? Math.round(data.total_duration / 1e6) : null,
    raw_preview: String(raw).slice(0, 300)
  }
}];

